    {
      "card_ids": ["C03"],
      "claim": "In healthy volunteers, chrysin at 400 mg had oral bioavailability estimated as less than 1%, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Predicted absolute oral bioavailability of chrysin in humans was 0.003–0.02%, well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In 12 human subjects, peonidin glycoside from WBB beverage had fractional systemic bioavailability of 0.32±0.05%, below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved human evidence, including numeric absolute/systemic bioavailability values and qualitative reports, indicates oral bioavailability far below 20%; therefore predict low.",
  "evidence_gaps": [
    "No retrieved record reports F >=20%; all numeric values are <1% or qualitative very low/poor.",
    "Some records are qualitative or based on CL/F rather than direct absolute bioavailability, but numeric records confirm very low bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

